-                .exposedHeaders("Location", "WWW-Authenticate");
+                // 13-5: 브라우저 JS가 429의 Retry-After를 읽으려면 노출해야 한다(CORS 기본 노출 헤더가 아니다)
+                .exposedHeaders("Location", "WWW-Authenticate", "Retry-After");
     }
 }

